mapper.select:
	SELECT

	FROM fw_intermediary_hire_info AS h
	JOIN fw_intermediary_org_basic AS i ON
		i.f_ID IN (SELECT fk_Intermediary_ID FROM fw_intermediary_info_hire_r WHERE fk_Hire_ID = h.f_ID AND f_IsDel = 0)
	LEFT JOIN fw_intermediary_hire_legal_team AS l ON
		l.fk_Org_Basic_Id = i.f_ID 
		AND l.fk_Hire_ID = h.f_ID
		AND l.f_Type = 0
		AND l.f_IsDel = 0
	WHERE h.f_IsDel = 0 AND i.f_IsDel = 0



        	AND h.f_Hire_State LIKE #{hireName }


        	AND h.f_Spe_Business_Name LIKE #{hireName }


        	AND (h.f_Spe_Business_Name LIKE #{hireName } OR h.f_Hire_State LIKE #{hireName })




        AND i.f_Org_Name LIKE #{intermediaryName }


        AND h.f_Hire_Type = #{bo.hireType }


        AND h.f_Hire_Way_Code = #{bo.hireWay }



        AND l.f_Lawyer_Name like #{lawyerName }
